void solve(int l, int r, int depth) {
    if (l > r) return;
    int mid = l;
    for (int i = l + 1; i <= r; i++) {
        if (a[i] < a[mid]) mid = i;
    }
    ans += (long long)b[mid] * depth;
    solve(l, mid - 1, depth + 1);
    solve(mid + 1, r, depth + 1);
}
