const int N = 1000010;
int prime[N], cnt;
bool st[N];
int f[N], g[N], num[N];

int main() {
    int n;
    cin >> n;
    f[1] = 1; g[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!st[i]) {
            prime[cnt++] = i;
            f[i] = 2;
            g[i] = 1 + i;
            num[i] = 1;
        }
        for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
            st[i * prime[j]] = true;
            if (i % prime[j] == 0) {
                num[i * prime[j]] = num[i] + 1;
                f[i * prime[j]] = f[i] / (num[i] + 1) * (num[i] + 2);
                g[i * prime[j]] = g[i] * prime[j] + 1;
                break;
            } else {
                num[i * prime[j]] = 1;
                f[i * prime[j]] = f[i] * 2;
                g[i * prime[j]] = g[i] * (1 + prime[j]);
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cout << i << ": f=" << f[i] << " g=" << g[i] << endl;
    }
    return 0;
}

