#include <iostream>
#include <atomic>
using namespace std;
template<typename T>
class LockFreeQueue{atomic<int>head{0},tail{0};T data[1024];
public:bool push(T v){int t=tail.load(memory_order_relaxed);int n=(t+1)%1024;if(n==head.load(memory_order_acquire))return false;
data[t]=v;tail.store(n,memory_order_release);return true;}
bool pop(T&v){int h=head.load(memory_order_relaxed);if(h==tail.load(memory_order_acquire))return false;
v=data[h];head.store((h+1)%1024,memory_order_release);return true;}};
int main(){return 0;}

